CREATE TABLE IF NOT EXISTS permission(id BIGINT PRIMARY KEY,name VARCHAR(50),code VARCHAR(100) UNIQUE,parent_id BIGINT DEFAULT 0,type INT DEFAULT 1,sort_order INT DEFAULT 0,url VARCHAR(255),create_time TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_permission(id BIGINT AUTO_INCREMENT PRIMARY KEY,role_id BIGINT,permission_id BIGINT);
CREATE TABLE IF NOT EXISTS role_change_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,role_id BIGINT,role_name VARCHAR(50),action VARCHAR(24),actor_id BIGINT,actor_name VARCHAR(50),before_snapshot CLOB,after_snapshot CLOB,note VARCHAR(255),create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
